# Upstream برای Gunicorn
upstream api_backend {
    server 127.0.0.1:8000 fail_timeout=0;
    keepalive 32;
}

# HTTP → HTTPS redirect
server {
    listen 80;
    listen [::]:80;
    server_name api.example.com;

    # ACME challenge برای Let's Encrypt
    location /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }

    location / {
        return 301 https://$host$request_uri;
    }
}

# HTTPS
server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name api.example.com;

    # SSL
    ssl_certificate /etc/letsencrypt/live/api.example.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/api.example.com/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
    ssl_prefer_server_ciphers on;
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 1d;
    ssl_session_tickets off;
    ssl_stapling on;
    ssl_stapling_verify on;

    # Security headers (backup — Django هم می‌فرستد)
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "DENY" always;

    # Client body size (برای آپلود فایل)
    client_max_body_size 20M;
    client_body_buffer_size 128k;

    # Timeouts
    client_body_timeout 60s;
    client_header_timeout 60s;
    send_timeout 60s;

    # Static files
    location /static/ {
        alias /var/www/library-api/staticfiles/;
        expires 30d;
        add_header Cache-Control "public, immutable";
        access_log off;
    }

    # Media files
    location /media/ {
        alias /var/www/library-api/media/;
        expires 7d;
        add_header Cache-Control "public";
    }

    # Health check (بدون log)
    location /health/ {
        proxy_pass http://api_backend;
        access_log off;
    }

    # API
    location / {
        # Rate limiting
        limit_req zone=api_limit burst=20 nodelay;

        # Proxy
        proxy_pass http://api_backend;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Connection "";

        # Timeouts
        proxy_connect_timeout 10s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;

        # Buffering
        proxy_buffering off;
        proxy_request_buffering off;

        # Retry
        proxy_next_upstream error timeout http_502 http_503 http_504;
    }
}

# Rate limiting zone
http {
    limit_req_zone $binary_remote_addr zone=api_limit:10m rate=100r/s;
    limit_req_status 429;

    # Gzip
    gzip on;
    gzip_vary on;
    gzip_min_length 1024;
    gzip_types application/json application/javascript text/css text/plain;
}

import time
from django.db import connection
from django.core.cache import cache
from django.conf import settings
from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import AllowAny
from rest_framework.response import Response
from rest_framework import status


START_TIME = time.time()


@api_view(["GET"])
@permission_classes([AllowAny])
def liveness(request):
    """
    آیا پروسه زنده است؟
    سریع، بدون بررسی وابستگی.
    """
    return Response({"status": "alive"})


@api_view(["GET"])
@permission_classes([AllowAny])
def readiness(request):
    """
    آیا آماده دریافت ترافیک است؟
    بررسی سریع دیتابیس و cache.
    """
    try:
        with connection.cursor() as cursor:
            cursor.execute("SELECT 1")
    except Exception:
        return Response(
            {"status": "not_ready", "reason": "database"},
            status=status.HTTP_503_SERVICE_UNAVAILABLE,
        )

    try:
        cache.set("health_check", "ok", timeout=5)
    except Exception:
        return Response(
            {"status": "not_ready", "reason": "cache"},
            status=status.HTTP_503_SERVICE_UNAVAILABLE,
        )

    return Response({"status": "ready"})


@api_view(["GET"])
@permission_classes([AllowAny])
def health(request):
    """
    گزارش کامل سلامت با جزئیات.
    """
    checks = {}
    overall_healthy = True

    # Database
    try:
        start = time.time()
        with connection.cursor() as cursor:
            cursor.execute("SELECT 1")
        checks["database"] = {
            "status": "ok",
            "latency_ms": round((time.time() - start) * 1000, 2),
        }
    except Exception as e:
        checks["database"] = {"status": "error", "error": str(e)}
        overall_healthy = False

    # Cache
    try:
        start = time.time()
        cache.set("health", "ok", timeout=5)
        assert cache.get("health") == "ok"
        checks["cache"] = {
            "status": "ok",
            "latency_ms": round((time.time() - start) * 1000, 2),
        }
    except Exception as e:
        checks["cache"] = {"status": "error", "error": str(e)}
        overall_healthy = False

    # Celery (اختیاری — به broker نگاه می‌کند)
    try:
        from library_system.celery import app as celery_app
        inspect = celery_app.control.inspect(timeout=2)
        stats = inspect.stats()
        if stats:
            checks["celery"] = {"status": "ok", "workers": len(stats)}
        else:
            checks["celery"] = {"status": "no_workers"}
    except Exception as e:
        checks["celery"] = {"status": "error", "error": str(e)}

    # Disk space
    import shutil
    try:
        total, used, free = shutil.disk_usage("/")
        free_percent = (free / total) * 100
        checks["disk"] = {
            "status": "ok" if free_percent > 10 else "warning",
            "free_percent": round(free_percent, 1),
        }
        if free_percent < 5:
            overall_healthy = False
    except Exception as e:
        checks["disk"] = {"status": "error", "error": str(e)}

    response_status = status.HTTP_200_OK if overall_healthy else status.HTTP_503_SERVICE_UNAVAILABLE
    return Response({
        "status": "healthy" if overall_healthy else "degraded",
        "uptime_seconds": int(time.time() - START_TIME),
        "version": getattr(settings, "GIT_SHA", "unknown"),
        "checks": checks,
    }, status=response_status)
